import json
import sys


def count_lines(tool_name, tool_input, count_mode="default"):
    lines = 0

    if tool_name == "Write":
        content = tool_input.get("content", "")
        lines = len(content.splitlines())

    elif tool_name == "Edit":
        new_string = tool_input.get("new_string", "")
        old_string = tool_input.get("old_string", "")

        if count_mode == "yc-mode":
            lines = len(new_string.splitlines())
        else:
            new_lines = len(new_string.splitlines())
            old_lines = len(old_string.splitlines())
            lines = new_lines - old_lines

    elif tool_name == "MultiEdit":
        edits = tool_input.get("edits", [])

        if count_mode == "yc-mode":
            lines = sum(len(edit.get("new_string", "").splitlines()) for edit in edits)
        else:
            lines = sum(
                len(edit.get("new_string", "").splitlines()) - len(edit.get("old_string", "").splitlines())
                for edit in edits
            )

    return lines


def handle_edit():
    from ahclaude_plugin.hook.logger import hook_log

    raw = sys.stdin.buffer.read()
    input_data = json.loads(raw.decode('utf-8'))

    session_id = input_data.get("session_id", "")
    tool_name = input_data.get("tool_name", "")
    tool_input = input_data.get("tool_input", {})
    file_path = tool_input.get("file_path", "")
    cwd = input_data.get("cwd", "")

    if not tool_name or not file_path:
        return

    if "/.claude/plans/" in file_path:
        return

    lines = count_lines(tool_name, tool_input)

    session_seq = 0
    current_turn = 0
    try:
        from ahclaude_plugin.session_cache import init_session, get_session_info
        if session_id:
            init_session(session_id)
            info = get_session_info(session_id)
            session_seq = info["session_seq"]
            current_turn = info["current_turn"]
    except Exception as e:
        hook_log("error", f"cmd_edit session_cache操作失败: {e}")

    try:
        from ahclaude_plugin.hook.logger import hook_log_raw
        from ahclaude_plugin.hook.report_helper import extract_accept_code_from_tool, report_adoption_for_edit

        accept_code = extract_accept_code_from_tool(tool_name, tool_input)
        accept_line_count = len(accept_code.splitlines())

        hook_log("edit", f"{tool_name} {file_path} lines={lines}", session_id=session_id)
        hook_log_raw("edit", input_data)

        report_adoption_for_edit(file_path, tool_name, accept_code, session_id,
                                  session_seq=session_seq, turn=current_turn,
                                  repository_path=cwd, accept_line_count=accept_line_count)
    except Exception as e:
        hook_log("error", f"cmd_edit logger/report操作失败: {e}")


if __name__ == "__main__":
    handle_edit()
